def can_obtain_24(n):
    if n < 2:
        return "NO"
    if n == 2:
        return "YES\n1 + 2 = 3" if n == 2 else "NO"

    operations = []
    numbers = list(range(1, n + 1))

    while len(numbers) > 1:
        a = numbers.pop()
        b = numbers.pop()
        operations.append(f"{a} + {b} = {a + b}")
        numbers.append(a + b)

    if numbers[0] == 24:
        return "YES\n" + "\n".join(operations)
    else:
        return "NO"

# Read input
n = int(input().strip())

# Get the result
result = can_obtain_24(n)

# Print the result
print(result)
